local S1, M1, A1 = 4218287579, 13808777, 1177026914
local S2 = 2111189339
local S3 = 3398490577
local K, C = 182463, 162148
local MASK = 4294967295

local function mul32(a, b)
	local alo = bit32.band(a, 65535)
	local ahi = bit32.rshift(a, 16)
	local blo = bit32.band(b, 65535)
	local bhi = bit32.rshift(b, 16)
	return bit32.band((bit32.band(alo * bhi + ahi * blo, 65535) * 65536) + alo * blo, 4294967295)
end

local ALPHABET = "lObKzEdnUyw2rqTsZBeACu6MJ/L7fp5xSIh0cjmGP+aFo4QV3tY1ikgDWHRXv8N9"
