local ORDER = { 46, 1, 47, 2, 48, 3, 49, 4, 50, 5, 51, 6, 52, 7, 53, 8, 54, 9, 55, 10, 56, 11, 57, 12, 58, 13, 59, 14, 60, 15, 61, 16, 62, 17, 63, 18, 64, 19, 65, 20, 66, 21, 67, 22, 68, 23, 69, 24, 70, 25, 71, 26, 72, 27, 73, 28, 74, 29, 75, 30, 76, 31, 77, 32, 78, 33, 79, 34, 80, 35, 81, 36, 82, 37, 83, 38, 84, 39, 85, 40, 86, 41, 87, 42, 88, 43, 89, 44, 90, 45, 91 }

local joined = table.create(#ORDER)
for i = 1, #ORDER do
	joined[i] = PARTS[ORDER[i]]
end
local BLOB = table.concat(joined)

local INDEX = {}
for i = 1, #ALPHABET do
	INDEX[string.sub(ALPHABET, i, i)] = i - 1
end

local stored = table.create(#BLOB * 3 // 4)
local buffer, bits = 0, 0
for i = 1, #BLOB do
	local ch = string.sub(BLOB, i, i)
	if ch ~= "=" then
		buffer = buffer * 64 + (INDEX[ch] or 0)
		bits = bits + 6
		if bits >= 8 then
			bits = bits - 8
			stored[#stored + 1] = math.floor(buffer / 2 ^ bits) % 256
			buffer = buffer % (2 ^ bits)
		end
	end
end

local count = #stored
local bytes = table.create(count)
local one, two, three = S1, S2, S3
for i = 0, count - 1 do
	one = bit32.band(mul32(one, M1) + A1, MASK)

	two = bit32.bxor(two, bit32.lshift(two, 13))
	two = bit32.bxor(two, bit32.rshift(two, 17))
	two = bit32.bxor(two, bit32.lshift(two, 5))

	three = bit32.band(three + 0x9E3779B9, MASK)
	local mixed = three
	mixed = bit32.bxor(mixed, bit32.rshift(mixed, 16))
	mixed = mul32(mixed, 0x85EBCA6B)
	mixed = bit32.bxor(mixed, bit32.rshift(mixed, 13))

	local key = bit32.bxor(bit32.bxor(bit32.band(one // 65536, 255), bit32.band(two, 255)),
		bit32.band(mixed, 255))

	local slot = ((i * K + C) % count) + 1
	bytes[i + 1] = string.char(bit32.bxor(stored[slot], key))
end

local source = table.concat(bytes)

local chunk, err = loadstring(source, "=krvx")
if not chunk then
	error("[krvx] " .. tostring(err), 0)
end

chunk(BLOB)
